-- Replace the inherited assessment bank with a curated, role-aware set.
-- Old rows are retained for historical responses but made inactive.

UPDATE public.questions SET active = false;

WITH category_data(name, description) AS (
  VALUES
    ('Communication', 'How clearly each person can express needs, uncertainty, feedback, and discomfort.'),
    ('Consent', 'Ongoing, specific, reversible consent and how it is checked in practice.'),
    ('Boundaries', 'Hard limits, soft limits, privacy boundaries, and pressure points.'),
    ('Safety Practices', 'Practical risk awareness before, during, and after intimacy or play.'),
    ('Aftercare', 'Emotional and physical care, decompression, and follow-up after intensity.'),
    ('Trust', 'Reliability, privacy, repair, and whether both people feel emotionally safe.'),
    ('Power Exchange', 'How authority, surrender, service, and control are negotiated and contained.'),
    ('Compatibility', 'Pace, intensity, expectations, and everyday relational fit.'),
    ('Conflict Resolution', 'How disagreement, disappointment, and misattunement are repaired.'),
    ('Relationship Goals', 'What each person wants the connection to become and how explicit that is.'),
    ('Red Flags', 'Clear warning signs around coercion, secrecy, retaliation, and unsafe escalation.'),
    ('Green Flags', 'Positive signs of mutual care, patience, humility, and collaborative decision-making.'),
    ('Emotional Intelligence', 'Self-awareness, regulation, empathy, and capacity to name feelings.'),
    ('Accountability', 'Ownership of mistakes, follow-through, and openness to feedback.'),
    ('BDSM Experience', 'Experience level, learning posture, and realistic understanding of risk.'),
    ('Dominant Skills', 'Dominant-side planning, leadership, restraint, and responsibility.'),
    ('Submissive Skills', 'Submissive-side agency, communication, recovery, and self-protection.'),
    ('Financial Responsibility', 'Money boundaries, gifts, dependency, and financial pressure.'),
    ('Attachment Style', 'Closeness, reassurance, independence, and fear responses.'),
    ('Community Involvement', 'Use of community, education, references, and external support.')
)
INSERT INTO public.question_categories (name, description)
SELECT name, description FROM category_data
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description;

WITH question_data(category_name, question, question_type, answer_options, weight, risk_level, order_index, branch_logic, applies_to) AS (
  VALUES
    ('Communication', 'When something feels off, how easy is it for you to say so before it becomes a bigger issue?', 'single_choice'::public.question_type, '[{"label":"I can usually say it early and plainly.","value":"strong","score":10},{"label":"I can say it, but I may need a little time.","value":"developing","score":4},{"label":"I often wait until I am sure it matters.","value":"unclear","score":0},{"label":"I usually hide it to avoid tension.","value":"risk","score":-10}]'::jsonb, 4, 'high'::public.risk_level, 10, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Communication', 'How do you prefer a partner to check whether you are still enjoying something?', 'single_choice'::public.question_type, '[{"label":"Direct verbal check-ins work well for me.","value":"strong","score":10},{"label":"A mix of verbal and non-verbal check-ins works best.","value":"developing","score":4},{"label":"I am still figuring out what helps.","value":"unclear","score":0},{"label":"I dislike check-ins because they break the mood.","value":"risk","score":-10}]'::jsonb, 3, 'medium'::public.risk_level, 11, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Communication', 'How comfortable are you asking clarifying questions when expectations are vague?', 'scale'::public.question_type, '[{"min":1,"max":10,"step":1}]'::jsonb, 2, 'low'::public.risk_level, 12, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Communication', 'If your partner misunderstands you, what is your usual next move?', 'single_choice'::public.question_type, '[{"label":"I slow down and restate what I meant.","value":"strong","score":10},{"label":"I try again later when we are calmer.","value":"developing","score":4},{"label":"I hope they work it out from context.","value":"unclear","score":0},{"label":"I get defensive or shut down.","value":"risk","score":-10}]'::jsonb, 3, 'medium'::public.risk_level, 13, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Communication', 'Which topics are easiest for you to discuss before intimacy or play?', 'multi_choice'::public.question_type, '[{"label":"Limits and hard no’s","value":"limits","score":3},{"label":"Desires and fantasies","value":"desires","score":3},{"label":"Health, stress, or triggers","value":"health","score":3},{"label":"Aftercare needs","value":"aftercare","score":3},{"label":"None of these feel easy yet","value":"none","score":-5}]'::jsonb, 2, 'low'::public.risk_level, 14, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Consent', 'What does ongoing consent look like to you in practice?', 'single_choice'::public.question_type, '[{"label":"We keep checking and either person can pause or change their mind.","value":"strong","score":10},{"label":"We agree upfront and check in if something changes.","value":"developing","score":4},{"label":"I understand the idea, but I am not always sure how to do it.","value":"unclear","score":0},{"label":"Once someone agreed, I expect them to continue.","value":"risk","score":-10}]'::jsonb, 5, 'critical'::public.risk_level, 15, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Consent', 'If your partner hesitates or seems unsure, what should happen next?', 'single_choice'::public.question_type, '[{"label":"Pause, check in, and make space for a real answer.","value":"strong","score":10},{"label":"Slow down and ask what would feel better.","value":"developing","score":4},{"label":"Keep going gently unless they say stop.","value":"unclear","score":0},{"label":"Treat hesitation as nerves and push through.","value":"risk","score":-10}]'::jsonb, 5, 'critical'::public.risk_level, 16, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
