    ('Consent', 'Can either person pause the dynamic without being punished, mocked, or guilted?', 'boolean'::public.question_type, '[{"label":"Yes","value":"yes","score":10},{"label":"Not yet / no","value":"no","score":-12}]'::jsonb, 5, 'critical'::public.risk_level, 18, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Consent', 'Before trying something new, what level of agreement feels right?', 'single_choice'::public.question_type, '[{"label":"Specific discussion of what is included, excluded, and how to stop.","value":"strong","score":10},{"label":"A shorter discussion if it is low intensity.","value":"developing","score":4},{"label":"General trust is usually enough.","value":"unclear","score":0},{"label":"The leading partner can decide in the moment.","value":"risk","score":-10}]'::jsonb, 4, 'high'::public.risk_level, 19, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
    ('Boundaries', 'How do you handle a partner naming a hard limit that disappoints you?', 'single_choice'::public.question_type, '[{"label":"I respect it without debate and adjust.","value":"strong","score":10},{"label":"I may feel disappointed, but I do not pressure them.","value":"developing","score":4},{"label":"I might ask once for context.","value":"unclear","score":0},{"label":"I try to persuade them if I really want it.","value":"risk","score":-10}]'::jsonb, 5, 'critical'::public.risk_level, 20, '{}'::jsonb, ARRAY['Dominant','submissive','switch']::text[]),
