INSERT INTO public.questions (category_id, question, question_type, answer_options, weight, risk_level, active, order_index, branch_logic, applies_to)
SELECT c.id, q.question, q.question_type, q.answer_options, q.weight, q.risk_level, true, q.order_index, q.branch_logic, q.applies_to
FROM question_data q
JOIN public.question_categories c ON c.name = q.category_name;
